import { z } from 'zod';

import { PlainText } from '../common/schemas/field-formats.js';

/* Request and response schemas never share a definition (AGENTS.md). Field rules are OQ-D. */

export const MAX_SEATS = 200;

const label = PlainText.trim().min(1).max(20);
const cubicleName = PlainText.trim().min(1).max(100);
const features = z
  .array(PlainText.trim().min(1).max(40))
  .max(10)
  .refine(
    (v) => new Set(v.map((f) => f.toLowerCase())).size === v.length,
    'Features must be unique (ignoring case)',
  );

/** Labels generated by a pattern, e.g. `A-1` to `A-20`; numbers are zero-padded to `padTo`. */
export function patternLabels(p: { prefix: string; from: number; to: number; padTo?: number }) {
  const out: string[] = [];
  for (let n = p.from; n <= p.to; n += 1) {
    out.push(`${p.prefix}${String(n).padStart(p.padTo ?? 1, '0')}`);
  }
  return out;
}

const pattern = z
  .strictObject({
    prefix: PlainText.max(15),
    from: z.int().min(0),
    to: z.int(),
    padTo: z.int().min(1).max(4).optional(),
  })
  .superRefine((p, ctx) => {
    if (p.to < p.from || p.to - p.from + 1 > MAX_SEATS) {
      ctx.addIssue({
        code: 'custom',
        path: ['to'],
        message: `Use a range of 1 to ${MAX_SEATS} seats, ending at or after the start`,
      });
      return;
    }
    const width = Math.max(String(p.to).length, p.padTo ?? 1);
    if (p.prefix.length + width > 20) {
      ctx.addIssue({
        code: 'custom',
        path: ['prefix'],
        message: 'Every label must be at most 20 characters',
      });
    }
  });

export const CreateSeatsInputSchema = z
  .union([
    z.strictObject({
      seats: z
        .array(
          z.strictObject({
            label,
            cubicleId: z.uuid().optional(),
            features: features.default([]),
          }),
        )
        .min(1)
        .max(MAX_SEATS),
    }),
    z.strictObject({
      pattern,
      cubicleId: z.uuid().optional(),
      features: features.default([]),
    }),
  ])
  .meta({ id: 'CreateSeatsInput' });
export type CreateSeatsInput = z.infer<typeof CreateSeatsInputSchema>;

export const UpdateSeatInputSchema = z
  .strictObject({
    label: label.optional(),
    cubicleId: z.uuid().nullable().optional(),
    features: features.optional(),
  })
  .refine((v) => Object.keys(v).length > 0, 'Send at least one field')
  .meta({ id: 'UpdateSeatInput' });
export type UpdateSeatInput = z.infer<typeof UpdateSeatInputSchema>;

export const CreateCubicleInputSchema = z
  .strictObject({ name: cubicleName })
  .meta({ id: 'CreateCubicleInput' });
export type CreateCubicleInput = z.infer<typeof CreateCubicleInputSchema>;

export const UpdateCubicleInputSchema = z
  .strictObject({ name: cubicleName })
  .meta({ id: 'UpdateCubicleInput' });

export const OwnerSeatSchema = z
  .object({
    id: z.uuid(),
    label: z.string(),
    features: z.array(z.string()),
    cubicle: z.object({ id: z.uuid(), name: z.string() }).nullable(),
    calendar: z.enum(['shared', 'own']),
    today: z.object({
      state: z.enum(['vacant', 'occupied', 'booked']),
      note: z.string().nullable(),
      markId: z.uuid().nullable(),
    }),
  })
  .meta({ id: 'OwnerSeat' });
export type OwnerSeat = z.infer<typeof OwnerSeatSchema>;

export const OwnerSeatListSchema = z
  .object({ items: z.array(OwnerSeatSchema) })
  .meta({ id: 'OwnerSeatList' });
export type OwnerSeatList = z.infer<typeof OwnerSeatListSchema>;

export const CubicleSchema = z
  .object({ id: z.uuid(), name: z.string(), seatCount: z.number().int() })
  .meta({ id: 'Cubicle' });
export type Cubicle = z.infer<typeof CubicleSchema>;

export const CubicleListSchema = z
  .object({ items: z.array(CubicleSchema) })
  .meta({ id: 'CubicleList' });
export type CubicleList = z.infer<typeof CubicleListSchema>;
